/**
 * Shell writes reuse the Write/Edit classifier for generated files, manifests, secrets and agent controls.
 * This is a best-effort text filter, not a sandbox. Each table pairs BLOCK with the nearest ALLOW:
 * neither a guard that allows everything nor one that refuses everything can pass.
 */
import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import { chmodSync, copyFileSync, mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import test from 'node:test';
import type { ExtensionAPI } from '@earendil-works/pi-coding-agent';
import registerCratisHooks from '../../.cratis/ai/harnesses/pi/extensions/cratis-hooks/index.ts';

const guard = resolve(import.meta.dirname, '../../.cratis/ai/hooks/scripts/cratis-guard-shell-writes.sh');
const BLOCK = 'block';
const ALLOW = 'allow';
const payload = (command: string, cwd: string) => ({ cwd, tool_name: 'Bash', tool_input: { command } });

function runGuard(input: object, cwd: string, env: NodeJS.ProcessEnv = {}) {
    const result = spawnSync('bash', [guard], { cwd, input: JSON.stringify(input), encoding: 'utf8', env: { ...process.env, CRATIS_HOOKS_ALLOW_PROTECTED_WRITES: '0', ...env } });
    assert.ok(result.status === 0 || result.status === 2, `unexpected guard exit ${result.status}: ${result.stderr}`);
    return { verdict: result.status === 2 ? BLOCK : ALLOW, stdout: result.stdout, stderr: result.stderr };
}

function runGuardAsync(input: object, cwd: string): Promise<ReturnType<typeof runGuard>> {
    return new Promise((resolveRun, reject) => {
        const child = spawn('bash', [guard], { cwd, env: { ...process.env, CRATIS_HOOKS_ALLOW_PROTECTED_WRITES: '0' } });
        let stdout = '';
        let stderr = '';
        child.stdout.setEncoding('utf8').on('data', chunk => { stdout += chunk; });
        child.stderr.setEncoding('utf8').on('data', chunk => { stderr += chunk; });
        child.on('error', reject);
        child.on('close', status => {
            if (status !== 0 && status !== 2) return reject(new Error(`unexpected guard exit ${status}: ${stderr}`));
            resolveRun({ verdict: status === 2 ? BLOCK : ALLOW, stdout, stderr });
        });
        child.stdin.on('error', () => {});
        child.stdin.end(JSON.stringify(input));
    });
}

async function forEachConcurrently<T>(items: T[], action: (item: T) => Promise<void>, limit = 16): Promise<void> {
    let next = 0;
    const failures: string[] = [];
    const worker = async () => {
        while (next < items.length) {
            try { await action(items[next++]); }
            catch (error) { failures.push((error as Error).message); }
        }
    };
    await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
    assert.equal(failures.join('\n'), '');
}

function scratchRepository(origin = 'https://github.com/example/app.git') {
    const root = mkdtempSync(join(tmpdir(), 'cratis-shell-writes-'));
    assert.equal(spawnSync('git', ['init', '-q', root]).status, 0);
    assert.equal(spawnSync('git', ['-C', root, 'remote', 'add', 'origin', origin]).status, 0);
    for (const directory of ['Source/Accounts/Registration', '.claude', '.pi/extensions', 'sub']) mkdirSync(join(root, directory), { recursive: true });
    writeFileSync(join(root, 'Source/Accounts/Registration/Registration.ts'), '// @generated by Cratis. DO NOT EDIT.\nexport class Register {}\n');
    writeFileSync(join(root, 'notes.md'), '# Notes\n\nThe marker is `// @generated by Cratis`.\n');
    writeFileSync(join(root, 'Directory.Packages.props'), '<Project />\n');
    writeFileSync(join(root, 'a.ts'), 'export {};\n');
    return { root, dispose: () => rmSync(root, { recursive: true, force: true }) };
}

test('literal shell write forms reuse the write classifier; reads and ordinary writes pass', async () => {
    const repo = scratchRepository();
    try {
        symlinkSync(join(repo.root, '.mcp.json'), join(repo.root, 'linked-control'));
        const cases: Array<[string, string]> = [
            [BLOCK, 'echo x > Directory.Packages.props'], [ALLOW, 'echo x > Directory.Packages.props.md'],
            ...['>>', '>|', '&>', '&>>', '2>', '1>>', '>&', '<>'].map(op => [BLOCK, `echo x ${op} .mcp.json`] as [string, string]),
            [BLOCK, 'echo x>.mcp.json'],
            [BLOCK, `echo x > '${repo.root}/.mcp.json'`], [ALLOW, "echo x > 'ordinary file.txt'"],
            [BLOCK, 'echo x > linked-control'], [ALLOW, 'echo x > ./--ordinary'],
            [BLOCK, "t'e'e $'\\x2e'mcp.json"], [ALLOW, "$'\\x74'ee notes.md"],
            [BLOCK, "echo x > $'\\056mcp\\u002ejson'"], [ALLOW, "echo x > $'out\\0.mcp.json'"],
            ...['echo x 2>&1', 'echo x >&2', 'echo x > /dev/null', "echo 'a > .mcp.json'", '# echo > .mcp.json', "grep '>' .mcp.json", 'cat < .mcp.json'].map(command => [ALLOW, command] as [string, string]),
            [BLOCK, 'printf x | tee -a .claude/settings.json'], [ALLOW, 'printf x | tee out.log'],
            [BLOCK, 'cp a.ts .mcp.json'], [ALLOW, 'cp .mcp.json /tmp/backup.json'],
            ...['cp a.ts b.ts .pi/extensions/', 'cp -t .pi/extensions a.ts', 'cp --target-directory=.pi/extensions a.ts', 'mv a.ts .claude/settings.local.json', 'install -m 644 a.ts global.json', 'ln -sf /tmp/x .mcp.json', 'cp -T a.ts .mcp.json'].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, 'install -d .pi/extensions'], [ALLOW, 'mv .claude x'],
            [BLOCK, "sed -i 's/a/b/' package-lock.json"], [ALLOW, "sed 's/a/b/' package-lock.json"],
            ...["sed -i '' s/a/b/ yarn.lock", 'sed -i.bak -e s/a/b/ yarn.lock', 'sed --in-place s/a/b/ yarn.lock'].map(command => [BLOCK, command] as [string, string]),
            [BLOCK, "perl -pi -e 's/a/b/' .env"], [ALLOW, 'perl -ne print .env'],
            [BLOCK, 'dd if=/dev/zero of=global.json'], [ALLOW, 'dd if=global.json of=/tmp/x'],
            [BLOCK, 'truncate -s 0 Source/Accounts/Registration/Registration.ts'], [ALLOW, 'truncate -s 0 notes.md'],
            [BLOCK, 'echo x >> Source/Accounts/Registration/Registration.ts'], [ALLOW, 'echo x >> notes.md'],
            ...['sudo tee .mcp.json', 'env FOO=1 cp a.ts .mcp.json', "bash -c 'echo x > .mcp.json'", 'eval "echo x > .mcp.json"', 'x=$(echo y > .mcp.json)', 'x=`echo y > .mcp.json`', 'echo x | tee >(cat > .mcp.json)', "bash <<'EOF'\necho x > .mcp.json\nEOF", 'ls | xargs -I{} cp a.ts .pi/extensions/'].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, "cat <<'EOF' > notes.md\necho x > .mcp.json\nEOF"], [ALLOW, "bash -c 'echo hi'"],
            [BLOCK, `bash <<< 'echo x > .mcp.json'`], [ALLOW, `cat <<< 'echo x > .mcp.json'`],
            [BLOCK, `bash <<'ONE' <<'TWO'\necho hi\nONE\necho x > .mcp.json\nTWO`],
            ...['doas -u user tee .mcp.json', 'command tee .mcp.json', 'builtin exec -a name tee .mcp.json', 'nohup nice -n 5 timeout -k 2 10 setsid tee .mcp.json', 'rtk proxy tee .mcp.json', 'env -u FOO -C.claude tee settings.json', 'env --chdir=.claude tee settings.json', `env --split-string='tee .mcp.json'`, 'cp -t.pi/extensions a.ts', 'cp --target-directory .pi/extensions a.ts', 'install -m644 -t.pi/extensions a.ts', 'cp -S.bak a.ts .mcp.json', 'tee -- .mcp.json', 'truncate --reference a.ts .mcp.json', "perl -i script.pl .mcp.json", "sed -i -f script.sed .mcp.json", 'if true; then echo x > .mcp.json; fi'].map(command => [BLOCK, command] as [string, string]),
            ...['nice -n 5 tee out.txt', 'timeout 10 tee out.txt', 'tee --output-error=warn out.txt', "sed -e 's/a/b/' .mcp.json", 'perl -e print .mcp.json', 'echo x 3>&-', 'echo x 0<&3'].map(command => [ALLOW, command] as [string, string]),
            [BLOCK, 'cd .claude && echo x > settings.json'], [ALLOW, 'cd sub && echo x > out.txt'],
            [BLOCK, 'env -C .claude tee settings.json'], [ALLOW, 'env -C sub tee out.txt'],
            [BLOCK, 'cp .env.example .env'], [ALLOW, 'cat .env.example'],
            [BLOCK, 'CRATIS_HOOKS_ALLOW_PROTECTED_WRITES=1 tee .mcp.json'],
            ...['git status', 'ls -la', 'echo x > ~/scratch.txt', 'touch .mcp.json', 'git restore .mcp.json'].map(command => [ALLOW, command] as [string, string]),
        ];
        await forEachConcurrently(cases, async ([expected, command]) => {
            const result = await runGuardAsync(payload(command, repo.root), repo.root);
            assert.equal(result.verdict, expected, `${command}\n${result.stderr}`);
            assert.equal(result.stdout, '', command);
            if (expected === BLOCK) {
                assert.match(result.stderr, /BLOCKED by cratis-guard-shell-writes/, command);
                assert.match(result.stderr, /BLOCKED by cratis-guard-writes/, command);
            } else assert.equal(result.stderr, '', command);
        });
    } finally { repo.dispose(); }
});

test('dynamic, pattern and unknown-directory destinations fail closed as specified', async () => {
    const repo = scratchRepository();
    try {
        const cases: Array<[string, string]> = [
            [BLOCK, 'cd "$D"/.claude && echo x > settings.json'], [BLOCK, 'cd "$D" && echo x > out.txt'], [ALLOW, 'cd sub && echo x > out.txt'],
            [BLOCK, 'f=.mcp.json; echo x > "$f"'], [ALLOW, 'echo x > "$out"'],
            [BLOCK, 'echo x > "$(git rev-parse --show-toplevel)/.mcp.json"'],
            [BLOCK, 'echo x > .cl*/settings.json'], [BLOCK, 'cp a.ts .{claude,pi}/x'],
            [BLOCK, 'f=.mcp.json; "$writer" out.txt'], [ALLOW, '"$writer" out.txt'],
            // D2: replacement sources make the destination basename dynamic; only the shell reason applies.
            [BLOCK, 'ls | xargs -I{} cp {} .pi/extensions/'], [ALLOW, 'ls | xargs -I{} cp {} out/'],
            [BLOCK, 'ls | xargs -J{} cp {} .pi/extensions/'], [BLOCK, 'ls | xargs --replace={} cp {} .pi/extensions/'],
            [BLOCK, 'ls | xargs cp a.ts .pi/extensions/'], [ALLOW, 'ls | xargs tee out.txt'],
            [BLOCK, 'echo x > ~somebody/.mcp.json'], [ALLOW, 'echo x > ~somebody/out.txt'],
            [BLOCK, 'popd; echo x > .mcp.json'], [BLOCK, 'popd; echo x > out.txt'], [ALLOW, 'cd -- sub; echo x > out.txt'],
            [BLOCK, `${'cd sub; '.repeat(9)}echo x > .mcp.json`], [BLOCK, `${'cd sub; '.repeat(9)}echo x > out.txt`], [ALLOW, 'echo x > /tmp/out.txt'],
            [BLOCK, 'echo x > ordinary*'], [ALLOW, "echo x > 'ordinary*'"],
            [BLOCK, "echo x > $'out\\tfile'"], [ALLOW, 'echo x > outfile'],
            [BLOCK, `tee ${Array.from({ length: 65 }, (_, i) => `out${i}`).join(' ')}`],
        ];
        await forEachConcurrently(cases, async ([expected, command]) => {
            const result = await runGuardAsync(payload(command, repo.root), repo.root);
            assert.equal(result.verdict, expected, `${command}\n${result.stderr}`);
            if (expected === BLOCK) assert.match(result.stderr, /BLOCKED by cratis-guard-shell-writes/, command);
            else assert.equal(result.stderr, '', command);
        });
    } finally { repo.dispose(); }
});

test('review regressions refuse shifted operands, hidden execution and unchecked shell input', async () => {
    const repo = scratchRepository();
    try {
        mkdirSync(join(repo.root, 'build'));
        writeFileSync(join(repo.root, 'build/.env'), 'secret');
        mkdirSync(join(repo.root, '.cratis'));
        writeFileSync(join(repo.root, '.cratis/ai.manifest.json'), '{}');
        const cases: Array<[string, string]> = [
            ...['cd -- /tmp; echo x > package.json', 'cd -P .claude; echo x > settings.json', 'cd -L .claude; echo x > settings.json', 'pushd -n .claude; tee settings.json', 'cd -; tee out.txt', 'cd; tee out.txt', 'popd; tee out.txt', 'pushd +1; tee out.txt', 'cd "$D"; tee out.txt'].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, 'cd -- sub && echo x > out.txt'], [ALLOW, 'cd -P sub && echo x > out.txt'],
            ...[`bash -c -- 'echo x > .env'`, `bash -c -e 'echo x > .env'`, `bash -O extglob -c 'echo x > .env'`, `sh -ec -- 'echo x > .env'`].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, `bash -c -- 'echo ok'`], [ALLOW, `bash -c -e 'echo ok'`],
            ...[`echo 'x > .env' | bash`, 'bash < script.sh', 'cat f | sh', 'cat f | bash -s', 'bash < <(cat f)', `cat <<'EOF'\necho ok\nEOF\nbash`, `bash <<< "$script"`].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, `bash <<'EOF'\necho ok\nEOF`], [ALLOW, `bash <<< 'echo ok'`], [ALLOW, 'npm test | tee log.txt'],
            ...['cp /tmp/x/.env .', 'cp /tmp/x/.env build/', 'cp -t build /tmp/x/.env', 'cp --no-target-directory a.ts .env', 'ln -sf a.ts .env', 'ln -t build /tmp/x/.env', 'install -D -m 600 a.ts .env', 'install -t build /tmp/x/.env', 'cp a.ts b.ts .env'].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, 'cp a.txt build/'], [ALLOW, 'cp a.txt b.txt build'], [ALLOW, 'cp -T /tmp/x/.env out.txt'],
            ...['echo ${x:-$(echo x > .env)}', 'echo $((1 + $(echo x > .env)))', 'echo $[1 + $(echo x > .env)]', '(( x = $(echo x > .env) ))', 'echo "${x:-$(echo x > .env)}"', 'echo "${x:-`echo x > .env`}"', 'echo ${x:-<(echo x > .env)}', 'echo ${x:-$(echo ")" > .env)}'].map(command => [BLOCK, command] as [string, string]),
            [BLOCK, `echo "\${x:-'$(echo x > .env)'}"`],
            [ALLOW, 'echo $((1 + $(echo 2)))'], [ALLOW, "echo '${x:-$(echo x > .env)}'"], [ALLOW, 'echo "literal <(echo x > .env)"'],
            ...['tee -a -- .env', 'tee -p .env', "sed -i'' -e s/a/b/ .env", 'sed -i.bak s/a/b/ .env', 'sed --in-place=.bak s/a/b/ .env', 'sed -E -i s/a/b/ .env', 'perl -pi -e s/a/b/ .env', 'perl -i.bak -e s/a/b/ .env', 'dd of=.env if=a.ts', 'truncate -s 0 .env', 'truncate --size=0 .env', 'truncate -r ref .env'].map(command => [BLOCK, command] as [string, string]),
            [ALLOW, 'sed -i.bak s/a/b/ notes.txt'], [ALLOW, 'truncate -r ref notes.txt'], [ALLOW, 'install -D -m 600 a.ts out.txt'],
            // Self-review: expansion of unquoted heredocs executes even when their consumer is not a shell.
            [BLOCK, 'cat <<EOF\n$(echo x > .env)\nEOF'], [BLOCK, 'cat <<EOF\n`echo x > .env`\nEOF'],
            [ALLOW, "cat <<'EOF'\n$(echo x > .env)\nEOF"],
            // Self-review: wrapper chdir flags must not hide the effective directory.
            [BLOCK, 'sudo -D .claude tee settings.json'], [BLOCK, 'sudo --chdir=.claude tee settings.json'],
            [ALLOW, 'sudo --chdir sub tee out.txt'],
            [BLOCK, 'install -Sdir a.ts .env'], [ALLOW, 'install -Sdir a.ts out.txt'],
            ...['.ENV', 'Package.json', 'Directory.packages.props', '.Claude/Settings.json', '.PI/Extensions/x.ts', '.Cratis/AI/rules/x.md'].map(file => [BLOCK, `echo x > ${file}`] as [string, string]),
            [ALLOW, 'echo x > Package.json.md'], [ALLOW, 'echo x > ENV.txt'],
        ];
        await forEachConcurrently(cases, async ([expected, command]) => {
            const result = await runGuardAsync(payload(command, repo.root), repo.root);
            assert.equal(result.verdict, expected, `${command}\n${result.stderr}`);
            assert.equal(result.stdout, '', command);
            if (expected === BLOCK) assert.match(result.stderr, /BLOCKED by cratis-guard-shell-writes/, command);
            else assert.equal(result.stderr, '', command);
        });
    } finally { repo.dispose(); }
});

test('manifest policy, managed trees, empty command and the harness escape hatch are preserved', () => {
    const repo = scratchRepository('https://github.com/Cratis/Example.git');
    try {
        assert.equal(runGuard(payload('echo x > Directory.Packages.props', repo.root), repo.root).verdict, ALLOW);
        mkdirSync(join(repo.root, '.cratis'), { recursive: true });
        writeFileSync(join(repo.root, '.cratis/ai.manifest.json'), '{}');
        const blocked = runGuard(payload('echo x >> .cratis/ai/rules/x.md', repo.root), repo.root);
        assert.equal(blocked.verdict, BLOCK);
        assert.match(blocked.stderr, /BLOCKED by cratis-guard-writes/);
        assert.equal(runGuard(payload('echo x > .mcp.json', repo.root), repo.root, { CRATIS_HOOKS_ALLOW_PROTECTED_WRITES: '1' }).verdict, ALLOW);
        assert.equal(runGuard({ tool_input: { file_path: '.mcp.json' } }, repo.root).verdict, ALLOW);
    } finally { repo.dispose(); }
});

test('the prefilter passes quote-split and ANSI-C command names to the parser', () => {
    const repo = scratchRepository();
    try {
        const stubs = join(repo.root, 'stubs');
        mkdirSync(stubs);
        writeFileSync(join(stubs, 'awk'), '#!/bin/sh\necho stub-awk-ran >&2\nexit 99\n');
        chmodSync(join(stubs, 'awk'), 0o755);
        const env = { PATH: `${stubs}:${process.env.PATH}` };
        for (const command of ['git status', 'ls -la']) assert.equal(runGuard(payload(command, repo.root), repo.root, env).stderr, '');
        for (const command of ["t'e'e .mcp.json", "$'\\x74'ee .mcp.json"]) {
            const result = runGuard(payload(command, repo.root), repo.root, env);
            assert.equal(result.verdict, BLOCK);
            assert.match(result.stderr, /stub-awk-ran/);
            assert.match(result.stderr, /parser failed/);
        }
    } finally { repo.dispose(); }
});

test('a missing or failed classifier refuses ordinary shell destinations', () => {
    const repo = scratchRepository();
    try {
        const scripts = join(repo.root, 'scripts');
        mkdirSync(scripts);
        const localGuard = join(scripts, 'cratis-guard-shell-writes.sh');
        copyFileSync(guard, localGuard);
        copyFileSync(join(guard, '../hook-lib.sh'), join(scripts, 'hook-lib.sh'));
        for (const classifier of [undefined, 'exit 7\n']) {
            if (classifier) writeFileSync(join(scripts, 'cratis-guard-writes.sh'), classifier);
            const result = spawnSync('bash', [localGuard], { cwd: repo.root, input: JSON.stringify(payload('echo x > out.txt', repo.root)), encoding: 'utf8', env: { ...process.env, CRATIS_HOOKS_ALLOW_PROTECTED_WRITES: '0' } });
            assert.equal(result.status, 2, result.stderr);
            assert.match(result.stderr, /could not check/);
            assert.match(result.stderr, /Do not retry/);
        }
    } finally { repo.dispose(); }
});

test('the Pi bridge refuses a shell write to agent controls', async () => {
    const saved = process.env.CRATIS_HOOKS_ALLOW_PROTECTED_WRITES;
    process.env.CRATIS_HOOKS_ALLOW_PROTECTED_WRITES = '0';
    const repo = scratchRepository();
    const handlers = new Map<string, (event: unknown, ctx: unknown) => Promise<unknown> | unknown>();
    registerCratisHooks({ on: (event: string, handler: (event: unknown, ctx: unknown) => unknown) => handlers.set(event, handler), registerTool: () => {} } as unknown as ExtensionAPI);
    try {
        const call = handlers.get('tool_call');
        assert.ok(call);
        const result = await call({ toolName: 'bash', input: { command: 'echo x > .mcp.json' } }, { cwd: repo.root }) as { block?: boolean; reason?: string };
        assert.equal(result?.block, true);
        assert.match(result?.reason ?? '', /BLOCKED by cratis-guard-shell-writes/);
        assert.equal(await call({ toolName: 'bash', input: { command: 'echo x > out.txt' } }, { cwd: repo.root }), undefined);
    } finally {
        if (saved === undefined) delete process.env.CRATIS_HOOKS_ALLOW_PROTECTED_WRITES;
        else process.env.CRATIS_HOOKS_ALLOW_PROTECTED_WRITES = saved;
        repo.dispose();
    }
});
